package com.rpsbattle.tournament;
import com.rpsbattle.tournament.domain.*;
import com.rpsbattle.tournament.persistence.*;
import com.rpsbattle.bot.upload.BotLanguage;
import com.fasterxml.jackson.databind.json.JsonMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
class TournamentBotPolicyTest {
 final com.fasterxml.jackson.databind.ObjectMapper json=JsonMapper.builder().addModule(new JavaTimeModule()).build();
 TournamentBotPolicy policy(String value)throws Exception{return json.readValue(value,TournamentBotPolicy.class);}
 @Test void legacyDefaultsAllowEveryExistingRuntimeIncludingJar(){var p=TournamentBotPolicy.defaults();assertThat(p.submissionMode()).isEqualTo(BotSubmissionMode.PRE_UPLOADED_ONLY);for(var language:BotLanguage.values())p.requirePreuploaded(language);assertThat(p.organizerSourceAccess()).isFalse();}
 @Test void codeOnlyAndLanguageRestrictionsAreEnforcedByDomainNotClient()throws Exception{var only=policy("{\"submissionMode\":\"CODE_IN_PLATFORM_ONLY\"}");for(var lang:BotLanguage.values())assertThatThrownBy(()->only.requirePreuploaded(lang)).hasMessage("PLATFORM_CODE_REQUIRED");var both=policy("{\"submissionMode\":\"BOTH\",\"allowedLanguages\":[\"PYTHON\",\"CPP\"]}");both.requirePreuploaded(BotLanguage.PYTHON);both.requirePreuploaded(BotLanguage.CPP);assertThatThrownBy(()->both.requirePreuploaded(BotLanguage.JAVA)).hasMessage("BOT_LANGUAGE_NOT_ALLOWED");assertThatThrownBy(()->both.requirePreuploaded(BotLanguage.JAR)).hasMessage("BOT_LANGUAGE_NOT_ALLOWED");}
 @Test void invalidWindowsLanguagesLimitsAndRuntimeOverridesAreRejected(){for(String value:List.of("{\"allowedLanguages\":[]}","{\"allowedLanguages\":[\"RUST\"]}","{\"allowedLanguages\":[null]}","{\"maxSubmissionVersions\":0}","{\"maxSourceBytes\":524289}","{\"cpuLimit\":10}","{\"memoryLimit\":4096}","{\"turnTimeoutMs\":0}","{\"organizerSourceAccess\":true}","{\"deadlineBehavior\":\"AUTO_SUBMIT_LATEST_READY\"}","{\"submissionOpenAt\":\"2026-10-20T10:00:00Z\",\"submissionDeadline\":\"2026-10-19T10:00:00Z\"}"))assertThatThrownBy(()->policy(value)).hasRootCauseMessage("INVALID_BOT_SUBMISSION_POLICY");}
 @Test void configurationRequiresOwnerFreshRevisionAndAnEmptyDraftAndRollsBack()throws Exception{var f=new TeamTournamentTest();var t=f.registry.create("Policy",TournamentFormat.ROUND_ROBIN);t.ownerUserId=f.a.id().value();var p=policy("{\"submissionMode\":\"BOTH\",\"allowedLanguages\":[\"PYTHON\"]}");assertThatThrownBy(()->f.owned.configureBotPolicy(f.bb,t.id,t.revision,p)).hasMessage("TOURNAMENT_FORBIDDEN");assertThatThrownBy(()->f.owned.configureBotPolicy(f.aa,t.id,-1L,p)).hasMessage("STALE_TOURNAMENT_REVISION");f.owned.configureBotPolicy(f.aa,t.id,t.revision,p);assertThat(t.botPolicy).isEqualTo(p);long revision=t.revision;doThrow(new IllegalStateException("offline")).when(f.repository).save(any());assertThatThrownBy(()->f.owned.configureBotPolicy(f.aa,t.id,revision,TournamentBotPolicy.defaults())).hasMessage("offline");assertThat(t.botPolicy).isEqualTo(p);assertThat(t.revision).isEqualTo(revision);t.status=TournamentStatus.REGISTRATION;assertThatThrownBy(()->f.owned.configureBotPolicy(f.aa,t.id,t.revision,p)).hasMessage("BOT_POLICY_LOCKED");}
 @Test void oldRegistrationAndQuickAddCannotBypassCodeOnly()throws Exception{var f=new TeamTournamentTest();var t=f.registry.create("Code only",TournamentFormat.ROUND_ROBIN);t.ownerUserId=f.a.id().value();t.botPolicy=policy("{\"submissionMode\":\"CODE_IN_PLATFORM_ONLY\"}");t.status=TournamentStatus.REGISTRATION;assertThatThrownBy(()->f.owned.register(f.aa,t.id,UUID.randomUUID().toString())).hasMessage("PLATFORM_CODE_REQUIRED");t.status=TournamentStatus.DRAFT;assertThatThrownBy(()->f.owned.add(f.aa,t.id,UUID.randomUUID().toString(),null,null)).hasMessage("PLATFORM_CODE_REQUIRED");verifyNoInteractions(f.bots);assertThat(t.registrations).isEmpty();}
 @Test void snapshotRestoresPolicyAndOldJsonWithoutPolicyKeepsLegacyDefaults()throws Exception{var t=new Tournament("x","x",TournamentFormat.ROUND_ROBIN,java.time.Instant.EPOCH);t.botPolicy=policy("{\"submissionMode\":\"BOTH\",\"allowedLanguages\":[\"CPP\"]}");var converter=new TournamentDetailsConverter();var encoded=converter.convertToDatabaseColumn(TournamentDetails.snapshot(t));var restored=new Tournament("x","x",t.format,t.createdAt);converter.convertToEntityAttribute(encoded).restore(restored);assertThat(restored.botPolicy).isEqualTo(t.botPolicy);var tree=json.readTree(encoded);((com.fasterxml.jackson.databind.node.ObjectNode)tree).remove("botPolicy");converter.convertToEntityAttribute(tree.toString()).restore(restored);assertThat(restored.botPolicy).isEqualTo(TournamentBotPolicy.defaults());}
}
